from html import escape as H

def detail(r, related, store_url):
 vid=r['video_id']; title=r['title']; slug=r['slug']
 intro=r.get('editorial_summary') or r['scene_notes']
 related_cards=''.join(f'<article class="video-related-card"><a href="/videos/{H(x["slug"],quote=True)}"><img src="/assets/videos/{H(x["video_id"],quote=True)}.jpg" width="480" height="360" loading="lazy" decoding="async" alt="Video thumbnail: {H(x["title"],quote=True)}"><span>{H(x["title"])}</span></a></article>' for x in related)
 if not related_cards:
  related_cards='<p>More HoopCut videos will appear here after they are published. Meanwhile, explore the guides below.</p>'
 return f'''<main id="main" class="watch-layout"><nav class="video-crumb" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><a href="/videos">Videos</a><span aria-hidden="true">/</span><span aria-current="page">{H(title)}</span></nav><div class="watch-grid"><article class="watch-primary"><div class="watch-player"><iframe src="https://www.youtube-nocookie.com/embed/{vid}?rel=0" title="{H(title,quote=True)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><h1>{H(title)}</h1><p class="video-intro">{H(intro)}</p><div class="video-facts"><span>Pickup basketball</span><span>{round(r['duration_seconds'])} seconds</span><span>Shot Tracer</span></div><div class="video-actions"><a class="primary" href="{H(store_url,quote=True)}" data-app-access="app-store" data-cta="video-detail">Get HoopCut on the App Store ↗</a><a class="secondary" href="https://www.youtube.com/shorts/{vid}">Watch on YouTube ↗</a></div><section class="video-notes"><h2>About this play</h2><p>{H(r.get('editorial_notes') or r['scene_notes'])}</p><p>Original footage: <a href="{H(r['source_url'],quote=True)}">watch the source video by @cantfakethetape ↗</a>. This HoopCut edit keeps the original creator’s on-screen branding.</p></section><section class="video-comments" aria-labelledby="comments-title" data-comments-video="{vid}"><div class="comments-heading"><h2 id="comments-title" data-comment-count>Comments</h2><label class="comments-sort">Sort by <select data-comment-sort aria-label="Sort comments"><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></label></div><div data-comment-compose></div><p class="comment-status" data-comment-status role="status" aria-live="polite">Loading comments…</p><button class="comment-button" type="button" data-comment-retry hidden>Retry</button><div data-comment-list></div><button class="comment-button" type="button" data-comment-more hidden>Load more comments</button><noscript><p>Enable JavaScript to read and post comments.</p></noscript></section><script src="/assets/comments.js" defer></script></article><aside class="watch-sidebar" aria-label="More basketball videos and guides"><section class="video-more"><h2>More videos</h2>{related_cards}<a href="/videos">Browse all videos →</a></section><section class="video-guides"><h2>Explore the workflow</h2><a href="/blog/how-to-add-shot-tracer-to-basketball-video">How to add Shot Tracer to basketball video →</a><a href="/demo/shot-tracer">See the prepared Shot Tracer demo →</a><a href="/blog/how-to-make-a-basketball-highlight-video">Make a basketball highlight video →</a><a href="/templates/basketball-clip-log">Log your best clips →</a></section></aside></div></main>'''

def index(records):
 cards=''
 for r in records:
  vid=r['video_id'];title=r.get('display_title') or r['title'].split(' | ')[0]
  cards+=f'<article class="video-tile"><a href="/videos/{H(r["slug"],quote=True)}"><img src="/assets/videos/{vid}.jpg" alt="{H(title,quote=True)}" width="1080" height="1920"><div class="tile-copy"><p class="video-kicker">Pickup basketball · {round(r["duration_seconds"])} sec</p><h2>{H(title)}</h2><p>Watch the clip →</p></div></a></article>'
 return '<main id="main"><nav class="video-crumb"><a href="/">HoopCut</a><span>/</span><span>Videos</span></nav><p class="video-kicker">HoopCut / On the court</p><h1>The game moves fast.<br>Keep the good parts.</h1><p class="index-lede">Basketball moments, cut down to the action. Watch the plays and follow each shot with HoopCut.</p><section class="video-grid" aria-label="Basketball videos">'+cards+'</section></main>'
